"""Data-derived aggregate report; never substitute historical result constants."""
import csv,json,os
from pathlib import Path
root=Path(os.environ.get('CLIF_FEDERATED_OUTPUT','output/run_federated_rehearsal_20261022'));report=root/'reports'
def read(name):
 with (report/'tables'/name).open() as f:return list(csv.DictReader(f))
def n(x):return float(x) if x else float('nan')
met=read('transport_metrics.csv');pool=read('pooled_associations.csv');counts=read('cohort_counts.csv')
labels={r['phenotype']:r['label'] for r in read('phenotype_labels.csv')}
manifest=json.loads((root/'coordinator/full/frozen_manifest.json').read_text())
held={s:json.loads((root/'coordinator'/('loo_'+s)/'frozen_manifest.json').read_text())['k'] for s in ['UCMC','NU','RUSH']}
lines=['Federated joint support–ARF primary analysis',str(root),'',f"Cohort: {sum(int(n(r['n'])) for r in counts):,} landmark hospitalizations; "+'; '.join(r['site']+' '+str(int(n(r['n']))) for r in counts)+'.',f"Full consensus: k={manifest['k']}, ID {manifest['consensus_id']}. Held-out discovery k: {held}.",'Labels derived from respiratory profiles, without outcomes:']
for ph,label in labels.items():lines.append('  '+label)
lines+=['','Core-adjusted cause-specific hospital death/hospice HRs through day 28 (reference P1):']
for r in pool:
 if r['model']=='core' and r['endpoint']=='death_or_hospice':
  if r['status']=='ok':lines.append(f"  {r['phenotype']}: HR {n(r['hazard_ratio']):.3f} ({n(r['hr_low']):.3f}–{n(r['hr_high']):.3f}); sites={r['k']}; I²={n(r['i2_percent']):.1f}%; prediction interval {n(r['hr_prediction_low']):.3f}–{n(r['hr_prediction_high']):.3f}.")
  else:lines.append(f"  {r['phenotype']}: {r['status']}; contributing sites={r['k']}.")
lines+=['','Held-out prediction: baseline | baseline+phenotype | baseline+simple summaries | baseline+summaries+phenotype']
for site in ['UCMC','NU','RUSH']:
 vals=[]
 for model in ['baseline','plus_phenotype','simple_summaries','summaries_plus_phenotype']:
  z=next(z for z in met if z['site']==site and z['model']==model and z['metric']=='auc')
  vals.append(f"{n(z['estimate']):.3f} ({n(z['conf_low']):.3f}–{n(z['conf_high']):.3f})")
 lines.append(site+': '+' | '.join(vals))
lines+=['','Incremental phenotype beyond simple summaries:']
for z in met:
 if z['model']=='phenotype_beyond_summaries' and z['metric']=='auc':lines.append(f"{z['site']}: ΔAUC {n(z['estimate']):+.4f} ({n(z['conf_low']):+.4f}–{n(z['conf_high']):+.4f}).")
lines+=['','Methods/limits: primary survivor/in-hospital ICU+72h landmark; bounded CLIFpy support waterfall with raw-evidence ARF; common-cost local OM (substitution 2, indel 1), Ward.D2 and 100 patient bootstraps; aggregate interval fingerprints; outcome-free shared discovery; frozen local assignments; support-insufficient status retained in all main analyses; all information-sufficient stays receive their nearest template. No support-coverage exclusion.','Site Cox models use available baseline covariates and patient-clustered uncertainty; REML modified Hartung–Knapp pooling. Sparse event partitions are withheld rather than fabricated. Core adjustment does not resolve missing clinical cancer stage, performance status, treatment intent or acute severity.','Held-out predictors exclude that site from template learning and coefficient fitting. Ridge-logistic coefficient synthesis is exploratory; unsupported predictive coefficients use flagged zero priors. Bootstrap uncertainty conditions on frozen training. Data have already been examined: this remains internal-external development, not untouched prospective validation.','Ordinal assignment agreement is not compared when full and held-out fits choose different k. Labels from separate fits are not clinical ground truth.','Separate complete score comparisons and federated sensitivities are generated by the reviewer-gap extension. APACHE II/IV cannot be validly calculated from these extracts; modified SOFA completeness/limitations must be reported.','No patient identifiers, individual sequences or predictions are in the staged aggregate returns. Logical federation on one machine is not OS isolation or differential privacy; linked-package disclosure review is still required before real institutional exchange.']
(report/'federated_rehearsal_report.txt').write_text('\n'.join(lines)+'\n')
print(report/'federated_rehearsal_report.txt')
